style.css:
@-moz-document domain("discord.com") {
body {
    background: url("https://i.imgur.com/xPz6vuZ.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Make app background transparent */
  .appMount-3lHmkl,
  .layers-3iHuyZ,
  .layer-86YKbF,
  .base-2jDfDU {
    background-color: rgba(0, 0, 0, 0.5) !important;
  }

  /* Transparent chat area with slight blur */
  .chatContent-3KubbW,
  .container-2o3qEW,
  .content-1jQy2l {
    background-color: rgba(0, 0, 0, 0.4) !important;
    backdrop-filter: blur(6px);
  }

  /* Sidebar transparency */
  .sidebar-1tnWFu {
    background-color: rgba(0, 0, 0, 0.4) !important;
    backdrop-filter: blur(4px);
  }

  /* Optional: change font color for better readability */
  .title-29uC1r,
  .markup-eYLPri {
    color: #ffffff !important;
  }
}
